@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700;800&family=Oswald:wght@500;600;700&display=swap');
:root{--ink:#f4f4e9;--muted:#9ba9a0;--lime:#c8f169;--dark:#071b16;--panel:#102820;--line:#284239;--orange:#ff9168}*{box-sizing:border-box}body{margin:0;background:var(--dark);color:var(--ink);font-family:'DM Sans',sans-serif;min-height:100vh;background-image:radial-gradient(ellipse at 70% -15%,#254335 0,transparent 42%),linear-gradient(135deg,#081c16,#071610 68%)}button{font:inherit;color:inherit;cursor:pointer;border:0}button:focus-visible{outline:2px solid var(--lime);outline-offset:3px}.app{max-width:1440px;margin:auto;padding:0 40px 30px}.topbar{height:82px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #ffffff15}.brand{display:flex;gap:12px;align-items:center;font-family:Oswald,sans-serif;font-size:23px;letter-spacing:1px}.brand-mark{width:34px;height:34px;border-radius:10px;background:var(--lime);color:#15271a;display:grid;place-items:center;font-size:20px;transform:rotate(-8deg)}.brand small{display:block;color:#9eafa5;font:10px 'DM Mono',monospace;letter-spacing:2px;margin-top:-3px}.top-right{display:flex;gap:10px;align-items:center;color:#b1beb6;font:11px 'DM Mono',monospace}.pill{border:1px solid var(--line);border-radius:100px;padding:8px 12px}.online{width:7px;height:7px;border-radius:50%;background:#c8f169;display:inline-block;margin-right:6px;box-shadow:0 0 10px #c8f169}.screen{display:none}.screen.active{display:block}.home{padding:42px 0 30px}.eyebrow{font:11px 'DM Mono',monospace;letter-spacing:2.5px;text-transform:uppercase;color:var(--lime)}.hero{display:flex;align-items:flex-end;justify-content:space-between;margin-bottom:32px}.hero h1,.subpage h1{font:600 clamp(54px,7vw,88px)/.91 Oswald,sans-serif;letter-spacing:1px;margin:17px 0}.hero h1 em,.subpage h1 em{font-style:normal;color:var(--lime)}.hero p,.subpage p{color:#aab8af;margin:0;font-size:15px}.hero-stats{display:flex;gap:32px;padding-bottom:7px}.hero-stats div{display:grid;gap:4px}.hero-stats b{font:600 28px Oswald}.hero-stats small,.muted{color:#819187;font:10px 'DM Mono',monospace;letter-spacing:1px}.home-grid{display:grid;grid-template-columns:1.55fr .82fr;gap:18px}.feature-card,.nav-card,.quote,.panel{background:#10241e;border:1px solid #ffffff12;border-radius:7px;overflow:hidden}.feature-card{padding:18px}.card-label,.moment-tag{font:10px 'DM Mono',monospace;letter-spacing:1.5px;color:#c0cdc4}.dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:var(--lime);margin-right:7px}.feature-art{height:300px;position:relative;overflow:hidden;margin-top:14px;background:linear-gradient(110deg,#345843,#6d8b53 52%,#213e30);border-radius:4px}.feature-art:before{content:'';position:absolute;inset:0;background:repeating-linear-gradient(90deg,transparent 0 90px,#ffffff08 90px 180px)}.art-glow{position:absolute;width:420px;height:420px;border-radius:50%;background:#c8f16930;filter:blur(50px);right:-60px;top:-210px}.art-lines{position:absolute;inset:18px;border:1px solid #e8f5d875;border-radius:2px}.art-lines:before{content:'';position:absolute;top:0;bottom:0;left:50%;border-left:1px solid #e8f5d875}.art-lines:after{content:'';position:absolute;width:120px;height:120px;border:1px solid #e8f5d875;border-radius:50%;left:calc(50% - 60px);top:calc(50% - 60px)}.art-ball{position:absolute;right:26%;top:38%;font-size:60px;filter:drop-shadow(0 10px 8px #11241877);transform:rotate(-23deg)}.art-copy{position:absolute;left:30px;bottom:26px;display:grid;gap:5px}.art-copy span{font:10px 'DM Mono',monospace;letter-spacing:2px;color:#e3efdc}.art-copy b{font:600 48px/.88 Oswald;letter-spacing:1px}.art-copy small{font:9px 'DM Mono',monospace;color:#e3efdc;margin-top:7px}.feature-footer{display:flex;align-items:center;justify-content:space-between;padding-top:18px}.feature-footer>div{display:grid;gap:6px}.feature-footer>div b{font-size:14px}.primary{background:var(--lime);color:#14261a;border-radius:4px;padding:14px 18px;font:600 11px 'DM Mono',monospace;letter-spacing:1px;transition:.2s}.primary:hover{background:#ddffa0;transform:translateY(-2px)}.primary span{font-size:17px;margin-left:12px}.side-cards{display:grid;grid-template-rows:1fr 1fr 1.16fr;gap:12px}.nav-card{padding:16px;display:flex;align-items:center;text-align:left;gap:13px;transition:.18s}.nav-card:hover{border-color:#c8f16975;transform:translateX(3px)}.nav-icon{height:39px;width:39px;display:grid;place-items:center;background:#203d30;border-radius:5px;color:var(--lime);font-size:22px}.nav-card span:nth-child(2){display:grid;gap:5px}.nav-card b{font-size:14px}.nav-card small{color:#8f9e94;font-size:11px}.arrow{margin-left:auto;color:var(--lime);font-size:19px}.quote{padding:18px 22px;position:relative;background:linear-gradient(120deg,#1d382b,#10241e)}.quote>span{font:64px Georgia;color:var(--lime);line-height:.7}.quote p{font:500 22px/1.2 Oswald;margin:7px 0 12px}.quote p em{font-style:normal;color:var(--lime)}.quote small{font:9px 'DM Mono',monospace;letter-spacing:1.6px;color:#8f9e94}.home-bottom,footer{display:flex;justify-content:space-between;color:#718177;font:9px 'DM Mono',monospace;letter-spacing:1.4px;margin-top:26px}.home-bottom span:first-child{color:#a2b1a6}footer{border-top:1px solid #ffffff12;padding-top:17px;margin-top:35px}footer i{color:var(--lime);font-style:normal}
/* match */
.match-top{height:74px;display:flex;justify-content:space-between;align-items:center}.back,.pause{font:10px 'DM Mono',monospace;letter-spacing:1px;color:#aab8af;background:transparent;padding:10px}.back:hover{color:var(--lime)}.pause{border:1px solid var(--line);border-radius:4px;font-size:17px;color:var(--lime)}.scoreboard{display:grid;grid-template-columns:55px auto 55px;align-items:center;justify-items:center;column-gap:13px;position:relative}.scoreboard>b{font:600 25px Oswald}.scoreboard>b i{color:#789083;font-style:normal;padding:0 8px}.club-short{font:10px 'DM Mono',monospace;color:var(--lime)}.club-short.away{color:#ff9976}.scoreboard>small{position:absolute;top:31px;left:50%;transform:translateX(-50%);font:10px 'DM Mono',monospace;color:#aab8af}.match-layout{display:grid;grid-template-columns:minmax(0,1fr) 260px;gap:15px}.pitch-wrap{position:relative;min-height:430px;overflow:hidden;border:1px solid #324c3c;background:#142e23;border-radius:5px}.pitch-wrap canvas{display:block;width:100%;height:100%;position:absolute;inset:0}.match-note{position:absolute;bottom:10px;left:12px;font:9px 'DM Mono',monospace;letter-spacing:1px;color:#d4dfd1;background:#091d17a6;border-radius:3px;padding:8px 9px}.live-dot{display:inline-block;width:6px;height:6px;background:#ff7959;border-radius:50%;margin-right:5px;box-shadow:0 0 9px #ff7959}.match-side{background:#10241e;border:1px solid #ffffff12;border-radius:5px;padding:15px;display:flex;flex-direction:column;gap:15px}.side-head{font:9px 'DM Mono',monospace;letter-spacing:1.5px;color:#9eafa5;display:flex;justify-content:space-between}.side-head span:first-child{color:var(--lime)}.moment{background:#1b3529;padding:16px;border-radius:4px;position:relative;overflow:hidden}.moment:after{content:'✦';position:absolute;right:-4px;top:3px;color:#ffffff0b;font-size:88px}.moment-tag{color:var(--lime);font-size:9px}.moment h2,.panel h2{font:500 27px/1.02 Oswald;margin:13px 0 8px}.moment p,.objective p{font-size:11px;line-height:1.6;color:#a5b3aa;margin:0 0 15px}.progress{height:4px;background:#ffffff17;border-radius:4px;overflow:hidden}.progress i{display:block;width:8%;height:100%;background:var(--lime);transition:width .5s}.match-stat{display:flex;justify-content:space-between;padding:1px 2px}.match-stat div{display:grid;gap:7px}.match-stat span{font:9px 'DM Mono',monospace;color:#8fa096;letter-spacing:1px}.match-stat b{font:19px Oswald}.match-stat b small{font-size:12px;color:#82948a}.crowd{margin-top:auto;padding:12px;background:#192f25;display:flex;align-items:center;gap:9px;color:var(--lime)}.crowd>span{font-size:19px}.crowd div:nth-child(2){display:grid;gap:4px}.crowd b{font:9px 'DM Mono',monospace;letter-spacing:.5px}.crowd small{font-size:10px;color:#91a197}.sound-bars{margin-left:auto;display:flex;align-items:center;gap:2px;height:20px}.sound-bars i{width:2px;height:9px;background:var(--lime);animation:wave .55s infinite alternate}.sound-bars i:nth-child(2){height:15px;animation-delay:.2s}.sound-bars i:nth-child(3){height:7px;animation-delay:.4s}.sound-bars i:nth-child(4){height:18px;animation-delay:.1s}.sound-bars i:nth-child(5){height:11px;animation-delay:.3s}@keyframes wave{to{transform:scaleY(.4)}}.controls{display:grid;gap:8px}.control-row{display:flex;align-items:center;gap:4px}.keycap{border:1px solid #465d50;background:#1a3026;min-width:24px;text-align:center;padding:5px 6px;border-radius:3px;font:9px 'DM Mono',monospace;color:#dae4d8}.keycap.wide{min-width:61px}.control-row small{font:9px 'DM Mono',monospace;color:#82948a;letter-spacing:.7px;margin-left:5px}.control-hint{font-size:10px;color:#85968b;border-top:1px solid #ffffff12;padding-top:9px}.touch-controls{display:none}.goal-flash{position:absolute;inset:0;pointer-events:none;background:#d7ff8770;opacity:0}.goal-flash.on{animation:flash .8s ease-out}@keyframes flash{0%{opacity:1}100%{opacity:0}}.pause-overlay,.full-overlay{display:none;position:fixed;inset:0;background:#06130fce;z-index:5;align-items:center;justify-content:center;backdrop-filter:blur(5px)}.pause-overlay.show,.full-overlay.show{display:flex}.modal{text-align:center;background:#102820;border:1px solid #ffffff20;border-radius:8px;padding:36px 44px;min-width:300px;box-shadow:0 20px 70px #0008}.modal h2{font:600 54px Oswald;margin:12px}.modal p{color:#a6b5aa;font-size:13px;margin:0 0 22px}.text-btn{display:block;margin:16px auto 0;background:none;color:#a1afa5;font:10px 'DM Mono',monospace;text-decoration:underline}.final-score{font:600 42px Oswald;margin:18px}.final-score i{font-style:normal;color:var(--lime)}
/* career + squad */
.subpage{padding:35px 0 10px}.subpage>.back{padding-left:0;margin-bottom:28px}.subpage h1{font-size:67px;margin:14px 0 25px}.career-grid{display:grid;grid-template-columns:1.5fr .8fr;gap:15px}.panel{padding:22px}.panel-top{display:flex;justify-content:space-between;font:10px 'DM Mono',monospace;color:#a7b5ab;letter-spacing:1px}.badge{color:var(--lime);border:1px solid #c8f16955;border-radius:20px;padding:6px 9px}.season-panel h2{font-size:28px}.season-panel>p{font-size:12px}.table{margin:23px 0}.table-row{display:grid;grid-template-columns:.45fr 2fr .55fr .55fr .55fr;align-items:center;min-height:38px;border-bottom:1px solid #ffffff10;font-size:11px;color:#adbbb1}.table-row span:first-child,.table-row span:nth-last-child(-n+3){font-family:'DM Mono',monospace}.table-head{font:9px 'DM Mono',monospace;color:#71847a;letter-spacing:1px;min-height:30px}.table-row.highlight{background:#1c3829;color:var(--lime);padding:0 7px;border:0}.season-panel>.primary{width:100%}.objective{background:linear-gradient(150deg,#1c3829,#10241e);position:relative;display:flex;flex-direction:column;min-height:320px}.obj-icon{font-size:35px;color:var(--lime);margin:26px 0 0}.objective h2{font-size:37px}.objective-foot{display:flex;justify-content:space-between;margin-top:auto;padding:15px 0 8px;font:9px 'DM Mono',monospace;color:#8fa095;letter-spacing:.5px}.objective-foot b{color:#d5e0d6}.squad-topline{display:flex;justify-content:space-between;align-items:center;margin-top:-12px;margin-bottom:20px}.squad-topline p{font-size:13px}.squad-list{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.player-card{display:flex;align-items:center;gap:11px;padding:13px;background:#10241e;border:1px solid #ffffff12;border-radius:5px}.avatar{height:40px;width:40px;display:grid;place-items:center;border-radius:4px;background:#203e30;color:var(--lime);font:600 17px Oswald}.player-info{display:grid;gap:4px;min-width:0}.player-info b{font-size:12px;white-space:nowrap}.player-info small{color:#8fa095;font:9px 'DM Mono',monospace;letter-spacing:.5px}.rating{margin-left:auto;font:600 20px Oswald;color:var(--lime)}.market-heading{margin:36px 0 14px;display:flex;justify-content:space-between;align-items:end}.market-heading h2{font:500 25px Oswald;margin:8px 0 0}.market-list{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.market-card{padding:15px;background:#10241e;border:1px solid #ffffff12;border-radius:5px;display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:12px}.market-card .avatar{background:#352f25;color:#ffbd75}.market-card .primary{padding:9px 11px;font-size:9px}.market-card .player-info b{font-size:12px}.toast{position:fixed;bottom:30px;left:50%;transform:translate(-50%,20px);background:var(--lime);color:#14261a;padding:12px 19px;border-radius:4px;font:11px 'DM Mono',monospace;opacity:0;transition:.25s;pointer-events:none;z-index:4}.toast.show{opacity:1;transform:translate(-50%,0)}
@media(max-width:850px){.app{padding:0 22px 24px}.match-layout{grid-template-columns:1fr}.match-side{display:grid;grid-template-columns:1fr 1fr;gap:10px}.side-head,.controls{grid-column:span 2}.moment{grid-row:span 2}.crowd{margin:0}.pitch-wrap{height:56vw;min-height:360px}.home-grid{grid-template-columns:1.2fr .8fr}.feature-art{height:270px}.career-grid{grid-template-columns:1.2fr .8fr}}
@media(max-width:600px){.app{padding:0 14px 18px}.topbar{height:66px}.brand{font-size:20px}.top-right .pill:first-child{display:none}.top-right{font-size:10px}.hero{padding-top:27px;align-items:flex-start;display:block}.hero h1{font-size:64px}.hero-stats{gap:23px;margin-top:24px}.hero-stats b{font-size:22px}.home-grid{grid-template-columns:1fr}.feature-card{padding:12px}.feature-art{height:250px}.art-copy{left:20px;bottom:20px}.art-copy b{font-size:41px}.side-cards{grid-template-rows:repeat(2,70px) 140px}.home-bottom span:last-child{display:none}.home-bottom{font-size:8px}.match-top{height:65px}.match-layout{gap:10px}.pitch-wrap{height:64vw;min-height:285px}.match-side{padding:11px;grid-template-columns:1fr 1fr}.moment{padding:12px}.moment h2{font-size:22px}.moment p{font-size:10px}.match-stat b{font-size:16px}.crowd{padding:8px;gap:6px}.crowd b{font-size:8px}.crowd small{font-size:9px}.controls{gap:5px}.control-hint{display:none}.touch-controls{display:flex;justify-content:space-between;align-items:center;padding:14px 10px 0}.dpad{display:grid;grid-template-columns:repeat(3,42px);grid-template-rows:repeat(2,38px);gap:3px}.dpad button{background:#183328;border:1px solid #3b5747;border-radius:5px;color:#d9e7d5;font-size:14px;touch-action:none}.dpad button:first-child{grid-column:2}.dpad button:nth-child(2){grid-column:1;grid-row:2}.dpad button:nth-child(3){grid-column:2;grid-row:2}.dpad button:nth-child(4){grid-column:3;grid-row:2}.touch-action{background:var(--lime);color:#14261a;border-radius:50%;height:74px;width:74px;font:600 10px 'DM Mono',monospace;line-height:1.5;box-shadow:0 4px 15px #c8f16930;touch-action:none}.touch-action small{font-size:8px}.career-grid{grid-template-columns:1fr}.subpage{padding-top:25px}.subpage h1{font-size:55px}.objective{min-height:250px}.squad-list{grid-template-columns:1fr 1fr;gap:7px}.player-card{padding:9px;gap:7px}.player-card .avatar{width:34px;height:36px}.player-info b{font-size:10px}.player-info small{font-size:8px}.rating{font-size:17px}.market-heading{align-items:flex-start;gap:10px}.market-heading>.muted{font-size:8px;text-align:right}.market-list{grid-template-columns:1fr}.market-card{padding:11px}.modal{padding:30px 26px;min-width:280px}.modal h2{font-size:48px}footer{font-size:8px}footer span:last-child{letter-spacing:.4px}}
@media(max-width:380px){.match-side{grid-template-columns:1fr}.moment{grid-row:auto}.controls,.side-head{grid-column:span 1}.crowd{grid-column:span 1}.squad-list{grid-template-columns:1fr}.pitch-wrap{min-height:250px}}

const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const baseSquad=[{name:'Milo Hart',pos:'GK',rating:68},{name:'Jae Okafor',pos:'DF',rating:67},{name:'Rory Bennett',pos:'DF',rating:65},{name:'Nico Silva',pos:'MF',rating:70},{name:'Eli Brooks',pos:'MF',rating:66},{name:'Tariq Vale',pos:'FW',rating:72}];
const freeAgents=[{name:'Amara Diallo',pos:'FW',rating:76,cost:480},{name:'Luca Moretti',pos:'MF',rating:73,cost:390},{name:'Finn Osei',pos:'DF',rating:71,cost:310}];
let save;try{save=JSON.parse(localStorage.touchlineSave)||null}catch{};if(!save)save={cash:1250,wins:0,goals:0,played:0,gd:0,points:0,squad:baseSquad.map(x=>({...x}))};
function persist(){localStorage.touchlineSave=JSON.stringify(save);updateHome()}
function updateHome(){$('#wallet').textContent='◈ '+save.cash.toLocaleString();$('#squadWallet').textContent='◈ '+save.cash.toLocaleString();$('#homeW').textContent=save.wins;$('#homeG').textContent=save.goals;$('#played').textContent=save.played;$('#gd').textContent=save.gd>0?'+'+save.gd:save.gd;$('#points').textContent=save.points;$('#careerProgress').textContent=`${save.played} / 8 MATCHES`;$('#careerBar').style.width=`${Math.min(100,save.played/8*100)}%`}
function screen(id){$$('.screen').forEach(e=>e.classList.toggle('active',e.id===id));if(id==='squad')renderSquad();if(id==='career')updateHome()}
$$('[data-screen]').forEach(b=>b.onclick=()=>screen(b.dataset.screen));$$('.homeBack').forEach(b=>b.onclick=()=>screen('home'));$('#playBtn').onclick=()=>startMatch();$('#careerPlay').onclick=()=>startMatch();
function renderSquad(){const list=$('#squadList');list.innerHTML=save.squad.map((p,i)=>`<article class="player-card"><div class="avatar">${p.pos}</div><div class="player-info"><b>${p.name}</b><small>${p.pos} · RIVETERS</small></div><div class="rating">${p.rating}</div></article>`).join('');$('#marketList').innerHTML=freeAgents.map((p,i)=>`<article class="market-card"><div class="avatar">${p.pos}</div><div class="player-info"><b>${p.name}</b><small>${p.pos} · ${p.rating} OVR · ◈ ${p.cost}</small></div><button class="primary sign-btn" data-index="${i}">SIGN</button></article>`).join('');$$('.sign-btn').forEach(b=>b.onclick=()=>signPlayer(+b.dataset.index))}
function signPlayer(i){const p=freeAgents[i];if(save.cash<p.cost){toast('NOT ENOUGH COINS FOR THIS DEAL.');return}if(save.squad.some(x=>x.name===p.name)){toast('THIS PLAYER IS ALREADY IN YOUR SQUAD.');return}save.cash-=p.cost;save.squad.push({name:p.name,pos:p.pos,rating:p.rating});persist();renderSquad();toast(`${p.name.toUpperCase()} HAS JOINED THE CLUB!`)}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2100)}
updateHome();
const canvas=$('#pitch'),ctx=canvas.getContext('2d');const W=1000,H=600;let players=[],ball={},running=false,paused=false,elapsed=0,last=0,raf=0,score=[0,0],shots=[0,0],possTime=[0,0],goalPause=0,controlled=1;const keys={};let moveTouch={x:0,y:0};
function resize(){const r=canvas.getBoundingClientRect();const d=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(r.width*d);canvas.height=Math.round(r.height*d)}new ResizeObserver(resize).observe(canvas);window.addEventListener('resize',resize);
function createPlayers(){const formations=[[130,300],[300,150],[300,300],[300,450],[430,215],[430,385]];players=[];for(let team=0;team<2;team++){for(let i=0;i<6;i++){let p=save.squad[i%save.squad.length];let f=formations[i];players.push({team,id:i,x:team===0?f[0]:W-f[0],y:f[1],homeX:team===0?f[0]:W-f[0],homeY:f[1],name:p.name,role:i===0?'GK':p.pos,rating:p.rating,vx:0,vy:0,stamina:1,anim:Math.random()*6})}}}
function resetKickoff(team=0){let p=players.find(p=>p.team===team&&p.id===2);p.x=team===0?475:525;p.y=300;ball={x:500,y:300,vx:0,vy:0,owner:p,r:8};controlled=1}
function startMatch(){screen('match');$('#pauseOverlay').classList.remove('show');$('#fullOverlay').classList.remove('show');score=[0,0];shots=[0,0];possTime=[0,0];elapsed=0;goalPause=0;paused=false;createPlayers();resetKickoff();updateHud();running=true;last=performance.now();cancelAnimationFrame(raf);raf=requestAnimationFrame(loop)}
function updateHud(){const mm=Math.min(90,Math.floor(elapsed/90*90));$('#clock').textContent=`${String(mm).padStart(2,'0')}:00`;$('#score').innerHTML=`${score[0]} <i>—</i> ${score[1]}`;let tot=possTime[0]+possTime[1];$('#poss').innerHTML=`${tot?Math.round(possTime[0]/tot*100):50}% <small>—</small> ${tot?Math.round(possTime[1]/tot*100):50}%` $('#shots').innerHTML=`${shots[0]} <small>—</small> ${shots[1]}`;let progress=Math.min(100,elapsed/90*100);$('#progress').style.width=`${Math.max(8,progress)}%`;if(elapsed<12){$('#momentTitle').innerHTML='Find your<br>first pass.';$('#momentText').textContent='Move into space and make the ball yours.'}else if(score[0]>score[1]){$('#momentTitle').innerHTML='Keep the<br>pressure on.';$('#momentText').textContent='The crowd can feel something building.'}else{$('#momentTitle').innerHTML='Make it<br>happen.';$('#momentText').textContent='One good move can change the whole game.'}}
function loop(now){if(!running)return;let dt=Math.min(.04,(now-last)/1000);last=now;if(!paused){if(goalPause>0){goalPause-=dt;if(goalPause<=0)resetKickoff(score[0]===score[1]?Math.random()<.5?0:1:score[0]>score[1]?1:0)}else{elapsed+=dt;simulate(dt);if(elapsed>=90){elapsed=90;finishMatch()}updateHud()}}draw();if(running)raf=requestAnimationFrame(loop)}
function axis(){let x=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0)+moveTouch.x;let y=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0)+moveTouch.y;let m=Math.hypot(x,y)||1;return{x:x/m,y:y/m,active:Math.hypot(x,y)>.1}}
