node <<'NODE'
const { spawn } = require('node:child_process');
const fs = require('node:fs');
const profile = '/tmp/opencode/touchline-chromium-' + process.pid;
const chrome = spawn('/usr/bin/chromium', ['--headless', '--no-sandbox', '--disable-gpu', '--no-first-run', '--no-default-browser-check', '--remote-debugging-port=9333', `--user-data-dir=${profile}`, 'http://localhost:3002/'], {stdio:'ignore'});
const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));
(async () => {
  try {
    let target;
    for (let i=0; i<40; i++) {
      try { const r=await fetch('http://localhost:9333/json'); target=(await r.json()).find(x=>x.type==='page'); if(target) break; } catch {}
      await sleep(250);
    }
    if (!target) throw new Error('Chromium debugging target did not start');
    const ws = new WebSocket(target.webSocketDebuggerUrl);
    await new Promise((resolve,reject)=>{ ws.onopen=resolve; ws.onerror=reject; });
    let id=0; const pending=new Map(); const errors=[];
    ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.method==='Runtime.exceptionThrown') errors.push(m.params.exceptionDetails.text);if(m.id&&pending.has(m.id)){pending.get(m.id)(m);pending.delete(m.id)}};
    const send=(method,params={})=>new Promise((resolve,reject)=>{const n=++id;pending.set(n,m=>m.error?reject(new Error(m.error.message)):resolve(m.result));ws.send(JSON.stringify({id:n,method,params}))});
    const evaluate=async expression=>(await send('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true})).result.value;
    await send('Page.enable'); await send('Runtime.enable');
    await sleep(700);
    console.log('home title:', await evaluate('document.title'));
    await evaluate("document.querySelector('#playBtn').click()"); await sleep(250);
    console.log('match opened:', await evaluate("document.querySelector('#match').classList.contains('active')"));
    await evaluate("document.querySelector('#pauseBtn').click()");
    console.log('pause overlay:', await evaluate("document.querySelector('#pauseOverlay').classList.contains('show')"));
    await evaluate("document.querySelector('#resumeBtn').click(); document.querySelector('#endBtn').click()");
    await evaluate("document.querySelector('[data-screen=squad]').click()");
    console.log('transfer cards:', await evaluate("document.querySelectorAll('.market-card').length"));
    await evaluate("document.querySelector('.sign-btn').click()");
    console.log('signed player in starting six:', await evaluate("document.querySelector('#squadList').textContent.includes('Amara Diallo') && document.querySelector('#squadList').textContent.includes('STARTING SIX')"));
    console.log('runtime exceptions:', errors.length ? errors.join(' | ') : 'none');
    ws.close();
  } catch (e) { console.error(e); process.exitCode=1; }
  finally { chrome.kill('SIGTERM'); try{fs.rmSync(profile,{recursive:true,force:true})}catch{} }
})();
